if db.execute("SELECT 1 FROM vaults WHERE name = ?", (vault,)).fetchone() is None:
    raise HTTPException(status_code=404, detail="No such vault")
rows = db.execute(
    "SELECT name, price FROM items WHERE vault = ? AND price >= ? ORDER BY price DESC",
    (vault, min_price),
).fetchall()
return {"count": len(rows), "total": sum(p for _, p in rows), "items": [n for n, _ in rows]}
